import { Tracker, sampleAt, roadLengthM } from './engine.js';

const $ = id => document.getElementById(id);
const ui = Object.fromEntries(['clock','themeSelect','wakeButton','settingsButton','safetyGate','parkedButton','demoSettings','speedWarning','deltaLabel','infoDrawer','closeInfoButton','drawerBackdrop','modeBadge','signalText','signalDot','setupPanel','liveButton','demoButton','drivePanel','changeModeButton','roadRef','roadDirection','instrumentGrid','speedStatus','speedValue','speedTrackFill','limitValue','deltaValue','deltaDescription','exitList','elapsedValue','accuracyValue','updatedValue','roadNote','trackingDiagnostics','demoControls','demoRoad','demoDirection','demoSpeed','demoSpeedOutput','demoPlayButton','networkText','coverageText','sourceText'].map(id => [id,$(id)]));
const STALE_MS = 15000;
const colorScheme=matchMedia('(prefers-color-scheme: dark)');
function applyTheme(choice){const resolved=choice==='system'?(colorScheme.matches?'dark':'light'):choice;document.documentElement.dataset.theme=resolved;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',resolved==='light'?'#e8efe5':'#101411');ui.themeSelect.value=choice;}
function initTheme(){let choice='system';try{choice=localStorage.getItem('delta-theme')||'system';}catch{}if(!['system','light','dark'].includes(choice))choice='system';applyTheme(choice);ui.themeSelect.addEventListener('change',()=>{try{localStorage.setItem('delta-theme',ui.themeSelect.value);}catch{}applyTheme(ui.themeSelect.value);});colorScheme.addEventListener('change',()=>{if(ui.themeSelect.value==='system')applyTheme('system');});}
let parkedConfirmed=false, dataReady=false;
let lastKnownEntryTime=null;
let roadsData, combinedData, tracker, mode = 'ready', watchId = null, staleTimer = null, demoTimer = null, demoRoad = null, demoChain = [], demoDistance = 0, demoClock = 0, lastDelta = null, demoPaused = false, lastFixTime = 0, wakeLock = null, lastFocus = null;
const roadList = () => roadsData?.roads || [];
const fmtTime = seconds => { const n=Math.max(0,Math.floor(seconds || 0)); return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`; };
const fmtDistance = m => m >= 1000 ? `${(m/1000).toFixed(m < 10000 ? 1 : 0)} km` : `${Math.max(0,Math.round(m/10)*10)} m`;
const fmtSigned = n => `${n < 0 ? '−' : '+'}${Math.abs(n).toFixed(1)}`;

function setSignal(message, tone='') { ui.signalText.textContent=message; ui.signalDot.className=`signal-dot ${tone}`; }
function setMode(next) { mode=next; ui.setupPanel.hidden=next!=='ready'; ui.drivePanel.hidden=next==='ready'; ui.demoControls.hidden=next!=='demo';ui.demoSettings.hidden=next!=='demo'; ui.modeBadge.textContent=next==='demo'?'DEMO · SIMULATED':next==='live'?'LIVE LOCATION':'READY'; ui.modeBadge.classList.toggle('demo',next==='demo'); }
function clearSession() { if(watchId!==null){navigator.geolocation?.clearWatch(watchId);watchId=null;} clearInterval(staleTimer);clearInterval(demoTimer);staleTimer=demoTimer=null; lastFixTime=0;lastDelta=null;lastKnownEntryTime=null; tracker?.reset(); demoPaused=false; ui.demoPlayButton.textContent='Pause demo'; }
function resetDashboard() { ui.instrumentGrid.classList.add('local-mode');ui.trackingDiagnostics.textContent='Waiting for a reliable road match.';ui.roadRef.textContent='—';ui.roadDirection.textContent='Locating road';ui.speedValue.textContent='—';ui.speedStatus.textContent='—';ui.speedTrackFill.style.width='0%';ui.limitValue.textContent='UNKNOWN';ui.deltaValue.textContent='—';ui.deltaValue.classList.remove('behind');ui.deltaLabel.textContent='REFERENCE INACTIVE';ui.speedWarning.hidden=true;ui.speedValue.classList.remove('overspeed');ui.deltaDescription.textContent='Waiting for a known road limit';ui.exitList.innerHTML='<li class="empty-exits">Upcoming exits will appear when the road is identified.</li>';ui.elapsedValue.textContent='00:00';ui.accuracyValue.textContent='—';ui.updatedValue.textContent='—';ui.roadNote.textContent='Road and speed data may be incomplete. Follow signs and road conditions.'; }
function render(state, fix) {
  lastKnownEntryTime=state?.entryTime||lastKnownEntryTime;const road=state?.road;ui.instrumentGrid.classList.toggle('local-mode',state?.status!=='tracking');
  ui.roadRef.textContent=road?.ref||(road?.kind==='ramp'&&road?.name==='Unnamed road'?'Ramp':road?.name)||'Road unidentified';
  ui.roadRef.parentElement.classList.toggle('local-road',!road?.isExpressway);
  ui.roadDirection.textContent=road ? [road.ref?road.name:null,road.travelDirection||road.direction,road.kind==='ramp'?'Ramp':null,state?.candidateRoad?`Checking ${state.candidateRoad.name||'new road'}`:null].filter(Boolean).join(' · ') : (state?.status==='gap'?'Outside mapped coverage':'Locating road');
  ui.speedValue.textContent=Number.isFinite(state?.speedKmh)?Math.round(state.speedKmh):'—';
  ui.speedStatus.textContent=state?.status==='tracking'?`MAINLINE · ${(state.confidence||'unknown').toUpperCase()}`:(state?.status||'IDENTIFYING').toUpperCase();
  ui.limitValue.textContent=Number.isFinite(state?.limitKmh)?`${Math.round(state.limitKmh)} KM/H`:'UNKNOWN';
  ui.speedTrackFill.style.width=Number.isFinite(state?.speedKmh)?`${Math.min(100,Math.max(0,state.speedKmh/120*100))}%`:'0%';
  const delta=state?.deltaSeconds;
  ui.deltaValue.textContent=Number.isFinite(delta)?fmtSigned(delta):'—';
  ui.deltaValue.style.setProperty('--delta-scale', String(Math.min(1,4/ui.deltaValue.textContent.length)));
  ui.deltaValue.classList.toggle('behind',Number.isFinite(delta)&&delta<-.05);ui.deltaLabel.textContent=Number.isFinite(delta)?delta<-.05?'DELTA NEGATIVE':delta>.05?'DELTA POSITIVE':'ON REFERENCE':'REFERENCE INACTIVE';
  ui.speedWarning.hidden=!(Number.isFinite(state?.speedKmh)&&Number.isFinite(state?.limitKmh)&&state.speedKmh>state.limitKmh);ui.speedValue.classList.toggle('overspeed',!ui.speedWarning.hidden);ui.limitValue.textContent=Number.isFinite(state?.limitKmh)?`${Math.round(state.limitKmh)} KM/H${state.limitAssumed?' · ASSUMED':''}`:'UNKNOWN';
  ui.deltaDescription.textContent=Number.isFinite(delta)?delta<0?'Ahead of reference pace · ease off if needed':delta>0?'Behind reference pace':'At reference pace':state?.status==='local'||road?.kind==='ramp'?'Expressway timing inactive on this road':'Confirming expressway mainline';
  ui.elapsedValue.textContent=fmtTime(state?.elapsedClockSeconds??state?.elapsedSeconds);
  ui.accuracyValue.textContent=Number.isFinite(fix?.accuracy)?`±${Math.round(fix.accuracy)} m`:'—';
  ui.updatedValue.textContent=fix?.timestamp?new Date(fix.timestamp).toLocaleTimeString('en-SG',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}):'—';
  const exits=(state?.exits||[]).slice(0,3);
  ui.exitList.replaceChildren();
  if(!exits.length){const li=document.createElement('li');li.className='empty-exits';li.textContent=road?'Exits available on confirmed expressway mainlines.':'Upcoming exits will appear when the road is identified.';ui.exitList.append(li);}
  for(const exit of exits){const li=document.createElement('li');const name=document.createElement('span');name.className='exit-name';name.textContent=exit.name||exit.ref||'Exit';const dist=document.createElement('span');dist.className='exit-distance';dist.textContent=Number.isFinite(exit.distanceM)?fmtDistance(exit.distanceM):'—';const deltaEl=document.createElement('span');deltaEl.className='exit-delta';deltaEl.textContent=Number.isFinite(exit.projectedDeltaSeconds)?`${fmtSigned(exit.projectedDeltaSeconds)}s est.`:'—';deltaEl.classList.toggle('ahead',exit.projectedDeltaSeconds<0);li.append(name,dist,deltaEl);ui.exitList.append(li);}
  ui.roadNote.textContent=state?.reason||(state?.status==='tracking'?state.fullSessionAvailable===false?'Session clock from first detection · pace segment since reacquisition.':'Tracking since estimated first mainline fix. Follow current signs.':state?.candidateRoad?'Checking road change · timing paused.':state?.status==='stale'?'Location lost · last known road shown. Pace unavailable; session clock continues.':road?.kind==='ramp'?'Ramp detected · expressway timing inactive.':state?.status==='local'?'Local road · speed only. Expressway timing inactive.':'Identifying road · expressway timing inactive.');ui.trackingDiagnostics.textContent=state?.entryTime?`Estimated first mainline detection: ${new Date(state.entryTime).toLocaleTimeString('en-SG',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false})}. Source: first reliable mainline fix, not a physical ramp crossing. ${state?.status==='stale'?'GPS signal lost; current speed and pace unavailable while the session clock continues.':state.fullSessionAvailable===false?'Full-session pace comparison unavailable after GPS gap; current pace is since reacquisition.':'Full-session pace comparison continues on a uniquely connected route.'} ${state.entryUncertaintyMs?`Entry uncertainty about ${Math.round(state.entryUncertaintyMs/1000)} seconds.`:''}`:state?.candidateRoad?`Checking ${state.candidateRoad.name||'new road'}; time and exits paused until confirmed.`:state?.status==='stale'?'GPS signal lost. Last known road retained; speed and pace unavailable. Elapsed session time continues from first detection.':'Waiting for a reliable road match.';
  if(mode==='live') setSignal(state?.status==='tracking'?`Live location · ${state.timingBasis||'since detection'} · estimated`:state?.status==='local'?'Live location · local road':state?.status==='entering'?'Live location · confirming expressway':state?.status==='exiting'?'Live location · leaving expressway':'Live location · identifying road',state?.status==='tracking'?'good':'warn');
}
function onFix(position){ if(mode!=='live')return; const c=position.coords;const fix={latitude:c.latitude,longitude:c.longitude,accuracy:c.accuracy,heading:c.heading,speed:c.speed,timestamp:position.timestamp};lastFixTime=Date.now();try{render(tracker.update(fix),fix);}catch(err){setSignal('Road data unavailable','warn');console.error(err);} }
function invalidateLocation(message){const state=tracker?.invalidate(message,true);if(state)render(state,null);else resetDashboard();ui.speedStatus.textContent='NO SIGNAL';setSignal(`${message} · last known road`, 'warn');}
function onLocationError(err){ if(mode!=='live')return;const text=err.code===1?'Location permission denied':err.code===2?'Location temporarily unavailable':'Location timed out';invalidateLocation(text); }
function startLive(){if(!parkedConfirmed)return;closeInfoIfOpen();clearSession();resetDashboard();setMode('live');setSignal('Requesting precise location…','warn');if(!roadsData||!tracker){setSignal('Road data unavailable · reload to retry','warn');return;}if(!navigator.geolocation){setSignal('Location unavailable in this browser','warn');return;}watchId=navigator.geolocation.watchPosition(onFix,onLocationError,{enableHighAccuracy:true,maximumAge:0,timeout:12000});staleTimer=setInterval(()=>{if(mode==='live'&&lastKnownEntryTime&&tracker?.state?.status==='stale')ui.elapsedValue.textContent=fmtTime((Date.now()-lastKnownEntryTime)/1000);if(mode==='live'&&lastFixTime&&Date.now()-lastFixTime>STALE_MS){lastFixTime=0;invalidateLocation('Location stale · waiting for signal');ui.speedStatus.textContent='STALE';}},1000);requestWake();}
function roadKey(road){return road.id||`${road.ref}|${road.direction}|${road.name}`;}
function buildDemoChains(ref){const byId=new Map(roadList().map(r=>[r.id,r]));return (roadsData.chains||[]).filter(c=>c.ref===ref).sort((a,b)=>b.lengthM-a.lengthM).slice(0,2).map(meta=>{const chain=[],seen=new Set();let road=byId.get(meta.firstRoadId);while(road&&!seen.has(road.id)&&road.chainId===meta.id){chain.push(road);seen.add(road.id);road=byId.get(road.nextRoadIds?.[0]);}chain.demoDirection=meta.travelDirection;return chain;});}
function populateDemo(){const refs=[...new Set(roadList().map(r=>r.ref).filter(Boolean))].sort();ui.demoRoad.replaceChildren(...refs.map(ref=>new Option(ref,ref)));if(refs.includes('BKE'))ui.demoRoad.value='BKE';updateDemoDirections();}
function updateDemoDirections(){const chains=buildDemoChains(ui.demoRoad.value);ui.demoDirection.replaceChildren(...chains.map((chain,i)=>new Option(`${{N:'Northbound',S:'Southbound',E:'Eastbound',W:'Westbound'}[chain.demoDirection]||'Direction'} · ${Math.round(chain.reduce((n,r)=>n+roadLengthM(r),0)/1000)} km`,String(i))));ui.demoDirection._chains=chains;selectDemoRoad();}
function selectDemoRoad(){demoChain=ui.demoDirection._chains?.[Number(ui.demoDirection.value)]||[];demoRoad=demoChain[0]||null;demoDistance=0;demoClock=Date.now();tracker?.reset();lastDelta=null;tickDemo(0);}
function tickDemo(seconds=1){if(mode!=='demo'||!demoRoad||demoPaused)return;const speed=Number(ui.demoSpeed.value);ui.demoSpeedOutput.value=`${speed} km/h`;const length=demoChain.reduce((n,r)=>n+roadLengthM(r),0);if(Number.isFinite(length)&&length>0)demoDistance=(demoDistance+speed/3.6*seconds)%length;let remaining=demoDistance,segment=demoChain[0];for(const road of demoChain){const n=roadLengthM(road);if(remaining<=n){segment=road;break;}remaining-=n;}const point=sampleAt(segment,remaining);if(!point)return;if(seconds>0)demoClock+=seconds*1000;const fix={...point,accuracy:5,speed:speed/3.6,timestamp:demoClock};try{render(tracker.update(fix),fix);}catch(err){setSignal('Demo road unavailable','warn');console.error(err);}setSignal('DEMO · simulated location','good');}
function startDemo(){if(!parkedConfirmed)return;closeInfoIfOpen();clearSession();resetDashboard();setMode('demo');if(!roadsData||!tracker){setSignal('Road data unavailable · reload to retry','warn');return;}populateDemo();demoTimer=setInterval(()=>tickDemo(1),1000);}
function showReady(){closeInfoIfOpen();clearSession();setMode('ready');setSignal('Choose a mode to begin');resetDashboard();}
async function requestWake(){if(!('wakeLock'in navigator)||document.visibilityState!=='visible'||mode==='ready')return;try{wakeLock=await navigator.wakeLock.request('screen');ui.wakeButton.setAttribute('aria-pressed','true');ui.wakeButton.textContent='Screen awake: on';wakeLock.addEventListener('release',()=>{wakeLock=null;ui.wakeButton.setAttribute('aria-pressed','false');ui.wakeButton.textContent='Screen awake: off';});}catch{ui.wakeButton.setAttribute('aria-pressed','false');ui.wakeButton.textContent='Screen awake unavailable';}}
async function toggleWake(){if(wakeLock){await wakeLock.release();wakeLock=null;}else await requestWake();}
function openInfo(){lastFocus=document.activeElement;ui.drawerBackdrop.hidden=false;ui.infoDrawer.hidden=false;ui.settingsButton.setAttribute('aria-expanded','true');ui.infoDrawer.focus();}
function closeInfoIfOpen(){if(!ui.infoDrawer.hidden)closeInfo();}
function closeInfo(){ui.drawerBackdrop.hidden=true;ui.infoDrawer.hidden=true;ui.settingsButton.setAttribute('aria-expanded','false');lastFocus?.focus();}
function syncVisibleHeight(){const height=window.visualViewport?.height||window.innerHeight;document.documentElement.style.setProperty('--visible-height',`${Math.round(height)}px`);}
function initEvents(){initTheme();syncVisibleHeight();window.visualViewport?.addEventListener('resize',syncVisibleHeight);window.addEventListener('resize',syncVisibleHeight);ui.parkedButton.addEventListener('click',()=>{parkedConfirmed=true;ui.safetyGate.hidden=true;if(dataReady)startLive();else setSignal('Loading Singapore road names…','warn');});if(!('wakeLock'in navigator)){ui.wakeButton.disabled=true;ui.wakeButton.textContent='Screen awake unavailable';}ui.liveButton.addEventListener('click',startLive);ui.demoButton.addEventListener('click',startDemo);ui.changeModeButton.addEventListener('click',showReady);ui.demoRoad.addEventListener('change',updateDemoDirections);ui.demoDirection.addEventListener('change',selectDemoRoad);ui.demoSpeed.addEventListener('input',()=>{ui.demoSpeedOutput.value=`${ui.demoSpeed.value} km/h`;});ui.demoPlayButton.addEventListener('click',()=>{demoPaused=!demoPaused;ui.demoPlayButton.textContent=demoPaused?'Resume demo':'Pause demo';setSignal(demoPaused?'DEMO · paused':'DEMO · simulated location',demoPaused?'warn':'good');});ui.wakeButton.addEventListener('click',toggleWake);ui.settingsButton.addEventListener('click',openInfo);ui.closeInfoButton.addEventListener('click',closeInfo);ui.drawerBackdrop.addEventListener('click',closeInfo);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!ui.infoDrawer.hidden)closeInfo();if(e.key==='Tab'&&!ui.infoDrawer.hidden){const focusable=[...ui.infoDrawer.querySelectorAll('button,a,[tabindex]:not([tabindex="-1"])')];if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0]?.focus();}}});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&mode!=='ready'&&!wakeLock)requestWake();});window.addEventListener('pagehide',()=>{clearSession();wakeLock?.release();});window.addEventListener('online',updateNetwork);window.addEventListener('offline',updateNetwork);}
function updateNetwork(){ui.networkText.textContent=navigator.onLine?'LOCAL SESSION':'OFFLINE · LOCAL SESSION';}
function updateClock(){ui.clock.textContent=new Date().toLocaleTimeString('en-SG',{hour:'2-digit',minute:'2-digit',hour12:false});}
async function init(){initEvents();updateClock();setInterval(updateClock,15000);updateNetwork();try{setSignal('Loading Singapore road names…','warn');const response=await fetch('./data/roads.json');if(!response.ok)throw new Error(`Road data ${response.status}`);roadsData=await response.json();let localData={roads:[]};try{if('DecompressionStream'in window){const compressed=await fetch('./data/local-roads.json.gz');if(!compressed.ok)throw new Error('Compressed road data unavailable');localData=await new Response(compressed.body.pipeThrough(new DecompressionStream('gzip'))).json();}else{const plain=await fetch('./data/local-roads.json');if(!plain.ok)throw new Error('Local road data unavailable');localData=await plain.json();}}catch(error){const plain=await fetch('./data/local-roads.json');if(!plain.ok)throw new Error('Local road data unavailable');localData=await plain.json();}combinedData={...roadsData,localRoads:localData.roads||[]};tracker=new Tracker(combinedData);const meta=roadsData.metadata||{};ui.coverageText.textContent=`Coverage includes ${new Set(roadList().map(r=>r.ref)).size} expressway references and ${(localData.roads||[]).length.toLocaleString()} additional road and ramp segments. Road names and speed are available beyond expressways; delta activates only on confirmed mainlines. Speed limits and exit locations may be missing or outdated. Missing or implausible speed tags use a clearly marked assumed 50 km/h reference. Pace delta starts only after confirmed mainline tracking.`;ui.sourceText.textContent=`Road data: ${meta.sourceAttribution||'© OpenStreetMap contributors'} · ${meta.license||'ODbL-1.0'}. ${meta.note||'Map data may be incomplete.'}`;dataReady=true;if(parkedConfirmed)startLive();else setSignal('Ready · confirm while parked to continue');}catch(err){console.error(err);setSignal('Road data unavailable','warn');}if('serviceWorker'in navigator){const hadController=!!navigator.serviceWorker.controller;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!hadController)return;const button=document.createElement('button');button.type='button';button.className='update-button';button.textContent='Update ready · reload while parked';button.addEventListener('click',()=>location.reload());ui.networkText.replaceChildren(button);},{once:true});navigator.serviceWorker.register('./sw.js').then(reg=>reg.update()).catch(()=>{});}}
init();
